import boto3


def stream_platform_generation(payload, config=None):
    config = config or {}
    client = boto3.client("bedrock-runtime", region_name=config.get("region", "us-east-1"))
    response = client.converse(
        modelId=payload["modelId"],
        messages=[{"role": "user", "content": [{"text": payload["text"]}]}],
        stream=True,
    )
    for event in response['events']:
        yield event

import boto3


def collect_platform_metadata(response):
    metadata = {
        "usage": response['usage'],
        "resourceId": response['modelId'],
        "modelHandle": response['modelId'],
    }
    return metadata

import boto3


def get_model_client(config=None):
    config = config or {}
    return boto3.client("bedrock-runtime", region_name=config.get("region", "us-east-1"))

from typing import Dict, Any


def normalize_request(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "text": payload["text"],
        "modelId": payload.get("modelId", "us.amazon.nova-pro-v1:0"),
    }


def normalize_response(response: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "text": ''.join(block['text'] for block in response['output']['message']['content'] if 'text' in block),
        "usage": response['usage'],
        "modelId": response['modelId'],
    }

import boto3


def embed_platform_output(text):
    client = boto3.client('sagemaker-runtime')
    response = client.invoke_endpoint(
        EndpointName='text-embedding-endpoint',
        ContentType='text/plain',
        Body=text,
    )
    return response['Body'].read().decode('utf-8')
